// @vitest-environment node
/**
 * SPEC-059: registro de ventanas desacopladas (src/main/detachedWindowRegistry.ts).
 * Módulo PURO — sus imports de electron son `import type`, así que se testea
 * sin mock de electron y con dobles mínimos de BrowserWindow/WebContents.
 * Cubre lo que sostiene la deduplicación (clave = componente) y la difusión de
 * `assistant:update` (filtrado de ventanas y webContents destruidos).
 * Generated by QA Dev agent.
 */
import type { BrowserWindow } from 'electron'
import { beforeEach, describe, expect, it } from 'vitest'
import {
  clearDetachedRegistry,
  getDetachedWindow,
  listDetachedWebContents,
  listDetachedWindows,
  registerDetachedWindow,
  unregisterDetachedWindow
} from '../../../src/main/detachedWindowRegistry'

interface FakeWindow {
  destroyed: boolean
  webContentsDestroyed: boolean
  isDestroyed: () => boolean
  webContents: { id: string; isDestroyed: () => boolean }
}

function fakeWindow(id: string): FakeWindow {
  const window: FakeWindow = {
    destroyed: false,
    webContentsDestroyed: false,
    isDestroyed: () => window.destroyed,
    webContents: { id, isDestroyed: () => window.webContentsDestroyed }
  }
  return window
}

/** Doble de BrowserWindow: el registro solo usa isDestroyed y webContents. */
function asWindow(value: FakeWindow): BrowserWindow {
  return value as unknown as BrowserWindow
}

beforeEach(() => {
  clearDetachedRegistry()
})

describe('detachedWindowRegistry (SPEC-059)', () => {
  it('returns null for a component with no registered window', () => {
    expect(getDetachedWindow('assistant')).toBeNull()
    expect(listDetachedWindows()).toEqual([])
    expect(listDetachedWebContents()).toEqual([])
  })

  it('registers one window per component and keeps both alive at the same time', () => {
    const assistant = fakeWindow('assistant-wc')
    const script = fakeWindow('script-wc')

    registerDetachedWindow('assistant', asWindow(assistant))
    registerDetachedWindow('script', asWindow(script))

    expect(getDetachedWindow('assistant')).toBe(asWindow(assistant))
    expect(getDetachedWindow('script')).toBe(asWindow(script))
    expect(listDetachedWindows()).toHaveLength(2)
  })

  it('replaces the previous window of the same component (dedup key = component)', () => {
    const first = fakeWindow('first')
    const second = fakeWindow('second')

    registerDetachedWindow('assistant', asWindow(first))
    registerDetachedWindow('assistant', asWindow(second))

    expect(getDetachedWindow('assistant')).toBe(asWindow(second))
    expect(listDetachedWindows()).toEqual([asWindow(second)])
  })

  it('unregisters a component and is idempotent', () => {
    registerDetachedWindow('script', asWindow(fakeWindow('script-wc')))

    unregisterDetachedWindow('script')
    expect(() => unregisterDetachedWindow('script')).not.toThrow()

    expect(getDetachedWindow('script')).toBeNull()
    expect(listDetachedWindows()).toEqual([])
  })

  it('filters destroyed windows out of the lookups and of the broadcast targets', () => {
    const alive = fakeWindow('alive-wc')
    const destroyed = fakeWindow('destroyed-wc')
    destroyed.destroyed = true
    registerDetachedWindow('assistant', asWindow(alive))
    registerDetachedWindow('script', asWindow(destroyed))

    expect(getDetachedWindow('script')).toBeNull()
    expect(listDetachedWindows()).toEqual([asWindow(alive)])
    expect(listDetachedWebContents()).toEqual([alive.webContents])
  })

  it('filters a destroyed webContents of a still-alive window (cierre en dos tiempos)', () => {
    const window = fakeWindow('half-dead-wc')
    window.webContentsDestroyed = true
    registerDetachedWindow('assistant', asWindow(window))

    expect(listDetachedWindows()).toHaveLength(1)
    expect(listDetachedWebContents()).toEqual([])
  })

  it('empties the registry with clearDetachedRegistry', () => {
    registerDetachedWindow('assistant', asWindow(fakeWindow('a')))
    registerDetachedWindow('script', asWindow(fakeWindow('s')))

    clearDetachedRegistry()

    expect(getDetachedWindow('assistant')).toBeNull()
    expect(getDetachedWindow('script')).toBeNull()
    expect(listDetachedWindows()).toEqual([])
  })
})
